CREATE TABLE `inventory_lots` (`id` text PRIMARY KEY NOT NULL,`product_code` text NOT NULL,`product_name` text NOT NULL,`received_quantity` integer NOT NULL,`remaining_quantity` integer NOT NULL,`expiry_date` text,`status` text DEFAULT 'ACTIVE' NOT NULL,`discount_rate` integer DEFAULT 0 NOT NULL,`note` text DEFAULT '' NOT NULL,`created_by` text NOT NULL,`created_at` integer NOT NULL,`updated_at` integer NOT NULL);
CREATE INDEX `inventory_lots_product_expiry_idx` ON `inventory_lots` (`product_code`,`expiry_date`);
CREATE TABLE `inventory_counts` (`id` text PRIMARY KEY NOT NULL,`status` text DEFAULT 'OPEN' NOT NULL,`started_by` text NOT NULL,`started_at` integer NOT NULL,`completed_by` text,`completed_at` integer);
CREATE TABLE `inventory_count_items` (`count_id` text NOT NULL,`product_code` text NOT NULL,`product_name` text NOT NULL,`expected_quantity` integer NOT NULL,`counted_quantity` integer,`difference` integer,`note` text DEFAULT '' NOT NULL,`updated_at` integer NOT NULL,PRIMARY KEY(`count_id`,`product_code`),FOREIGN KEY (`count_id`) REFERENCES `inventory_counts`(`id`) ON UPDATE no action ON DELETE cascade);
CREATE TABLE `smaregi_stock_snapshots` (`product_code` text NOT NULL,`product_id` text NOT NULL,`store_id` text NOT NULL,`stock_amount` integer NOT NULL,`layaway_stock_amount` integer DEFAULT 0 NOT NULL,`source_updated_at` text,`synced_at` integer NOT NULL,PRIMARY KEY(`product_code`,`store_id`));
CREATE TABLE `inventory_events` (`id` text PRIMARY KEY NOT NULL,`event_type` text NOT NULL,`product_code` text,`quantity` integer,`details_json` text DEFAULT '{}' NOT NULL,`actor` text NOT NULL,`created_at` integer NOT NULL);
CREATE INDEX `inventory_events_created_idx` ON `inventory_events` (`created_at`);
